/// <summary>
/// Cash report DP
/// </summary>
[SRSReportParameterAttribute(classStr(AVARUMCashSalesSummaryContract))]
internal final class AVARUMCashSalesSummaryDP     extends   SrsReportDataProviderBase
{
    AVARUMCashSalesCashVoucherTmp    cashVoucherTmp;
    AVARUMCashSalesDeskBalanceTmp    deskBalanceTmp;

}

Method.Source:
/// <summary>
/// Gets the cash voucher temp table dataset
/// </summary>
/// <returns>Cash voucher temp table</returns>
[SRSReportDataSetAttribute(tableStr(AVARUMCashSalesCashVoucherTmp))]
public AVARUMCashSalesCashVoucherTmp getCashVoucherTmp()
{
    select * from cashVoucherTmp;
    return cashVoucherTmp;
}

/// <summary>
/// Gets the desk balance temp table dataset
/// </summary>
/// <returns>Desk balance temp table</returns>
[SRSReportDataSetAttribute(tableStr(AVARUMCashSalesDeskBalanceTmp))]
public AVARUMCashSalesDeskBalanceTmp getDeskBalanceTmp()
{
    select * from deskBalanceTmp;
    return deskBalanceTmp;
}

/// <summary>
/// Processes the report by populating temp tables
/// </summary>
public void processReport()
{
    AVARUMCashSalesSummaryContract   contract;
    AVARUMCashSalesCashVoucher      cashVoucher;
    AVARUMCashSalesDeskBalance      deskBalance;
    TransDate                       reportDate;

    contract   = this.parmDataContract() as AVARUMCashSalesSummaryContract;
    reportDate = contract.parmTransDate();

    // Populate cash voucher temp table
    while select cashVoucher
        where cashVoucher.CreatedDateTime >= DateTimeUtil::newDateTime(reportDate, 0)
           && cashVoucher.CreatedDateTime < DateTimeUtil::newDateTime(reportDate + 1, 0)
    {
        cashVoucherTmp.CashVoucher    = cashVoucher.CashVoucher;
        cashVoucherTmp.AmountMST      =  cashVoucher.AmountMST;
        cashVoucherTmp.GrossAmount    =  cashVoucher.GrossAmount;
        cashVoucherTmp.insert();
    }

    // Populate desk balance temp table
    while select deskBalance
        where deskBalance.OpenAt >= DateTimeUtil::newDateTime(reportDate, 0)
           && deskBalance.OpenAt < DateTimeUtil::newDateTime(reportDate + 1, 0)
    {
        deskBalanceTmp.SalesId     =  deskBalance.SalesId;
        deskBalanceTmp.CloseAmount =  deskBalance.CloseAmount;
        deskBalanceTmp.OpenAmount  =  deskBalance.OpenAmount;
        deskBalanceTmp.ClosedAt    =  deskBalance.ClosedAt;
        deskBalanceTmp.OpenAt      =  deskBalance.OpenAt;
        deskBalanceTmp.DeskId      =  deskBalance.DeskId;
        deskBalanceTmp.insert();
    }
}
